{
  "name": "Tecan Freedom EVO 自动化液体处理工作站",
  "name_en": "Tecan Freedom EVO automated liquid handling workstation",
  "manufacturer": "Tecan",
  "description": "一款用于实验室自动移液与板件搬运的台式自动化工作站，通常配备多通道 LiHa 液体处理臂，可完成吸液、分液、液面探测、一次性吸头装卸及多轴定位，并可结合 96 通道或板搬运模块执行样品制备、微孔板加样和高通量实验流程。",
  "description_en": "A benchtop automated liquid handling workstation for laboratory pipetting and plate movement. It typically includes a multichannel LiHa liquid handling arm for aspirating, dispensing, liquid level detection, disposable tip handling, and multi-axis positioning, and may work with 96-channel or plate-handling modules for sample preparation, microplate filling, and high-throughput workflows.",
  "tag_hints": [
    "automated liquid handling",
    "multichannel pipetting",
    "disposable tip handling",
    "liquid level detection",
    "microplate automation",
    "plate transport",
    "high-throughput screening",
    "Tecan Freedom EVO"
  ],
  "actions": [
    {
      "action_name": "auto-parse_response",
      "description": "解析仪器返回数据。",
      "description_en": "Parse responses returned by the instrument."
    },
    {
      "action_name": "auto-send_command",
      "description": "向仪器发送控制命令。",
      "description_en": "Send a control command to the instrument."
    },
    {
      "action_name": "auto-num_channels",
      "description": "获取液体处理通道数量。",
      "description_en": "Get the number of liquid-handling channels."
    },
    {
      "action_name": "auto-liha_connected",
      "description": "获取 LiHa 液体处理臂是否已连接。",
      "description_en": "Get whether the LiHa liquid handling arm is connected."
    },
    {
      "action_name": "auto-roma_connected",
      "description": "获取 RoMa 板搬运模块是否已连接。",
      "description_en": "Get whether the RoMa plate-handling module is connected."
    },
    {
      "action_name": "auto-pnp_connected",
      "description": "获取 PnP 模块是否已连接。",
      "description_en": "Get whether the PnP module is connected."
    },
    {
      "action_name": "auto-mca_connected",
      "description": "获取 MCA 多通道模块是否已连接。",
      "description_en": "Get whether the MCA multichannel module is connected."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出设备配置或状态表示。",
      "description_en": "Serialize the device configuration or state."
    },
    {
      "action_name": "auto-setup_arm",
      "description": "设置并初始化机械臂。",
      "description_en": "Set up and initialize the arm."
    },
    {
      "action_name": "auto-aspirate",
      "description": "通过选定通道吸取液体。",
      "description_en": "Aspirate liquid through the selected channels."
    },
    {
      "action_name": "auto-dispense",
      "description": "通过选定通道分配液体。",
      "description_en": "Dispense liquid through the selected channels."
    },
    {
      "action_name": "auto-pick_up_tips",
      "description": "拾取一次性吸头。",
      "description_en": "Pick up disposable tips."
    },
    {
      "action_name": "auto-drop_tips",
      "description": "丢弃一次性吸头。",
      "description_en": "Drop disposable tips."
    },
    {
      "action_name": "auto-pick_up_tips96",
      "description": "拾取 96 通道吸头。",
      "description_en": "Pick up 96-channel tips."
    },
    {
      "action_name": "auto-drop_tips96",
      "description": "丢弃 96 通道吸头。",
      "description_en": "Drop 96-channel tips."
    },
    {
      "action_name": "auto-aspirate96",
      "description": "执行 96 通道吸液。",
      "description_en": "Perform 96-channel aspiration."
    },
    {
      "action_name": "auto-dispense96",
      "description": "执行 96 通道分液。",
      "description_en": "Perform 96-channel dispensing."
    },
    {
      "action_name": "auto-pick_up_resource",
      "description": "拾取实验资源或板件。",
      "description_en": "Pick up a lab resource or plate."
    },
    {
      "action_name": "auto-move_picked_up_resource",
      "description": "移动已拾取的实验资源或板件。",
      "description_en": "Move a picked-up lab resource or plate."
    },
    {
      "action_name": "auto-drop_resource",
      "description": "放下已搬运的实验资源或板件。",
      "description_en": "Drop the transported lab resource or plate."
    },
    {
      "action_name": "auto-can_pick_up_tip",
      "description": "获取是否可以拾取吸头。",
      "description_en": "Get whether a tip can be picked up."
    },
    {
      "action_name": "auto-position_initialization_x",
      "description": "执行 X 轴初始化定位。",
      "description_en": "Initialize and home the X axis."
    },
    {
      "action_name": "auto-report_x_param",
      "description": "获取 X 轴参数。",
      "description_en": "Get X-axis parameters."
    },
    {
      "action_name": "auto-report_y_param",
      "description": "获取 Y 轴参数。",
      "description_en": "Get Y-axis parameters."
    },
    {
      "action_name": "auto-initialize_plunger",
      "description": "初始化柱塞和阀驱动。",
      "description_en": "Initialize the plunger and valve drive."
    },
    {
      "action_name": "auto-report_z_param",
      "description": "获取 Z 轴参数。",
      "description_en": "Get Z-axis parameters."
    },
    {
      "action_name": "auto-report_number_tips",
      "description": "获取机械臂上的吸头数量。",
      "description_en": "Get the number of tips on the arm."
    },
    {
      "action_name": "auto-position_absolute_all_axis",
      "description": "将各轴移动到绝对位置。",
      "description_en": "Move all axes to absolute positions."
    },
    {
      "action_name": "auto-position_valve_logical",
      "description": "设置各通道阀的逻辑位置。",
      "description_en": "Set the logical valve position for each channel."
    },
    {
      "action_name": "auto-set_end_speed_plunger",
      "description": "设置柱塞末端速度。",
      "description_en": "Set the plunger end speed."
    },
    {
      "action_name": "auto-move_plunger_relative",
      "description": "相对移动柱塞以吸液或分液。",
      "description_en": "Move the plungers relatively for aspiration or dispensing."
    },
    {
      "action_name": "auto-set_detection_mode",
      "description": "设置液面检测模式。",
      "description_en": "Set the liquid detection mode."
    },
    {
      "action_name": "auto-set_search_speed",
      "description": "设置液面搜索速度。",
      "description_en": "Set the liquid search speed."
    },
    {
      "action_name": "auto-set_search_retract_distance",
      "description": "设置液面搜索回撤距离。",
      "description_en": "Set the retract distance for liquid search."
    },
    {
      "action_name": "auto-set_search_submerge",
      "description": "设置液面搜索后的下探深度。",
      "description_en": "Set the submerge distance for liquid search."
    },
    {
      "action_name": "auto-set_search_z_start",
      "description": "设置液面搜索起始高度。",
      "description_en": "Set the liquid search start height."
    },
    {
      "action_name": "auto-set_search_z_max",
      "description": "设置液面搜索最大 Z 高度。",
      "description_en": "Set the maximum Z height for liquid search."
    },
    {
      "action_name": "auto-set_z_travel_height",
      "description": "设置 Z 轴行进高度。",
      "description_en": "Set the Z-axis travel height."
    },
    {
      "action_name": "auto-move_detect_liquid",
      "description": "下降探针以检测液面并下探。",
      "description_en": "Move down to detect liquid and submerge."
    },
    {
      "action_name": "auto-set_slow_speed_z",
      "description": "设置 Z 轴慢速速度。",
      "description_en": "Set the slow Z-axis speed."
    },
    {
      "action_name": "auto-set_tracking_distance_z",
      "description": "设置吸液或分液时的 Z 轴跟踪距离。",
      "description_en": "Set the Z-axis tracking distance used during aspiration or dispensing."
    },
    {
      "action_name": "auto-move_tracking_relative",
      "description": "执行同步跟踪相对运动。",
      "description_en": "Perform a synchronous relative tracking movement."
    },
    {
      "action_name": "auto-move_absolute_z",
      "description": "以慢速将 Z 轴移动到绝对位置。",
      "description_en": "Move the Z axis to absolute positions at slow speed."
    },
    {
      "action_name": "auto-set_stop_speed_plunger",
      "description": "设置柱塞停止速度。",
      "description_en": "Set the plunger stop speed."
    },
    {
      "action_name": "auto-get_disposable_tip",
      "description": "拾取一次性吸头。",
      "description_en": "Pick up disposable tips."
    },
    {
      "action_name": "auto-discard_disposable_tip_high",
      "description": "在高位丢弃一次性吸头。",
      "description_en": "Discard disposable tips at a high Z position."
    },
    {
      "action_name": "auto-report_r_param",
      "description": "获取 R 轴参数。",
      "description_en": "Get R-axis parameters."
    },
    {
      "action_name": "auto-report_g_param",
      "description": "获取 G 轴参数。",
      "description_en": "Get G-axis parameters."
    },
    {
      "action_name": "auto-set_smooth_move_x",
      "description": "设置 X 轴平滑移动参数。",
      "description_en": "Set the X-axis smooth-move parameter."
    },
    {
      "action_name": "auto-set_fast_speed_x",
      "description": "设置 X 轴快速速度。",
      "description_en": "Set the fast speed for the X axis."
    },
    {
      "action_name": "auto-set_fast_speed_y",
      "description": "设置 Y 轴快速速度。",
      "description_en": "Set the fast speed for the Y axis."
    },
    {
      "action_name": "auto-set_fast_speed_z",
      "description": "设置 Z 轴快速速度。",
      "description_en": "Set the fast speed for the Z axis."
    },
    {
      "action_name": "auto-set_fast_speed_r",
      "description": "设置 R 轴快速速度。",
      "description_en": "Set the fast speed for the R axis."
    },
    {
      "action_name": "auto-set_vector_coordinate_position",
      "description": "设置矢量坐标位置。",
      "description_en": "Set the vector coordinate position."
    },
    {
      "action_name": "auto-action_move_vector_coordinate_position",
      "description": "移动到矢量坐标位置。",
      "description_en": "Move to the vector coordinate position."
    },
    {
      "action_name": "auto-position_absolute_g",
      "description": "将 G 轴移动到绝对位置。",
      "description_en": "Move the G axis to an absolute position."
    },
    {
      "action_name": "auto-set_gripper_params",
      "description": "设置夹爪参数。",
      "description_en": "Set gripper parameters."
    },
    {
      "action_name": "auto-grip_plate",
      "description": "夹取微孔板或实验板件。",
      "description_en": "Grip a microplate or lab plate."
    },
    {
      "action_name": "auto-set_target_window_class",
      "description": "设置与设备控制通信使用的目标窗口类别。",
      "description_en": "Set the target window class used for communication with the instrument control software."
    }
  ]
}

